async function fn(b){const{data:{session}}=await sb.auth.getSession(),r=await fetch((CFG.API||'')+'/api/migrate-users',{method:'POST',headers:{Authorization:'Bearer '+session.access_token,apikey:CFG.KEY},body:JSON.stringify(b)});if(!r.ok)throw Error(await r.text());return r.json()}
