function mig(){main(`<h2>Migrasi Data</h2><div class=form><h3>1. Ekspor migrasi penuh</h3><p>Semua vendor, pengguna (tanpa password), seluruh data, token link, audit log, dan file (logo, QRIS, bukti bayar) dalam satu ZIP.</p><button onclick=migExp()>Ekspor Migrasi Penuh</button><h3>2. Impor ke Supabase baru</h3><p>Jalankan di instance <b>baru</b> yang sudah berisi schema + semua migrasi dan punya admin. Panduan: <code>MIGRASI.md</code>.</p><label>File ZIP<input id=mf type=file accept=".zip"></label><label>Password sementara semua pengguna (min 8)<input id=mp type=password></label><button onclick=migImp()>Mulai impor</button><pre id=ml style="white-space:pre-wrap"></pre><p id=er class=err></p></div>`)}
async function migExp(){try{$('#ml').textContent='';await loadZip();const z=new JSZip(),tables={},files={logos:[],proofs:[]},fail=[];
 for(const t of MIG){tables[t]=await pageAll(t);ml(`${t}: ${tables[t].length}`)}
 const u=await fn({action:'export'});
 const add=async(bk,p)=>{try{const{data,error}=await sb.storage.from(bk).download(p);if(error)throw error;z.file(`files/${bk}/${p}`,data);files[bk].push(p)}catch(e){fail.push(bk+'/'+p)}};
 for(const v of tables.vendors)for(const k of ['logo_url','qris_url']){const m=(v[k]||'').match(/\/object\/public\/logos\/(.+)$/);if(m)await add('logos',decodeURIComponent(m[1]))}
 for(const p of tables.payments)if(p.proof_path)await add('proofs',p.proof_path);
 ml(`file: ${files.logos.length+files.proofs.length} berhasil, ${fail.length} gagal`);
 z.file('data.json',JSON.stringify({app:'vendor-crm',kind:'full-migration',version:APP_VERSION,exported_at:new Date().toISOString(),source:CFG.URL,tables,auth_users:u.users,files,failed:fail}));
 await sb.rpc('log_export',{p_vendor:null});
 dl(`migrasi-penuh-${new Date().toISOString().slice(0,10)}.zip`,await z.generateAsync({type:'blob',compression:'DEFLATE'}));ml('Selesai ✓ Simpan ZIP di tempat aman (berisi data sensitif).')}catch(x){$('#er').textContent=x.message}}
async function migImp(){try{$('#ml').textContent='';const f=$('#mf').files[0],pw=$('#mp').value;if(!f)throw Error('Pilih file ZIP');if(pw.length<8)throw Error('Password minimal 8 karakter');await loadZip();
 const z=await JSZip.loadAsync(f),d=JSON.parse(await z.file('data.json').async('string'));if(d.app!=='vendor-crm'||d.kind!=='full-migration')throw Error('Bukan file migrasi penuh');
 if(d.version!==APP_VERSION&&!confirm(`Versi file ${d.version} berbeda dengan aplikasi ${APP_VERSION}. Pastikan skema database sama. Lanjutkan?`))return;
 if(!confirm('Impor ke instance INI? Data ber-ID sama dilewati, data lain ditambahkan.'))return;
 for(const bk of ['logos','proofs'])for(const p of d.files[bk]){const e=z.file(`files/${bk}/${p}`);if(!e)continue;const b=new Blob([await e.async('arraybuffer')],{type:CT[p.split('.').pop().toLowerCase()]||''}),{error}=await sb.storage.from(bk).upload(p,b);if(error&&!/exist|duplicate/i.test(error.message))ml(`⚠ ${bk}/${p}: ${error.message}`)}
 ml('file diunggah');
 d.tables.vendors.forEach(v=>['logo_url','qris_url'].forEach(k=>{const m=(v[k]||'').match(/\/object\/public\/logos\/(.+)$/);if(m)v[k]=sb.storage.from('logos').getPublicUrl(decodeURIComponent(m[1])).data.publicUrl}));
 const ok=new Set(),U=d.auth_users||[];
 for(let i=0;i<U.length;i+=20){const r=await fn({action:'import',users:U.slice(i,i+20),password:pw});r.results.forEach(x=>{if(x.status==='created'||x.status==='exists_id')ok.add(x.id);else ml(`⚠ dilewati: ${x.email} (${x.status})`)})}
 ml(`pengguna: ${ok.size}/${U.length}`);d.tables.profiles=d.tables.profiles.filter(p=>ok.has(p.id));
 for(const t of MIG){const rows=d.tables[t]||[];let n=0;for(let i=0;i<rows.length;i+=200){const{data,error}=await sb.rpc('import_bulk',{p_table:t,p_rows:rows.slice(i,i+200),p_first:i===0});if(error)throw Error(t+': '+error.message);n+=data}ml(`${t}: ${n}/${rows.length}`)}
 ml('Selesai ✓ Minta pengguna login dengan password sementara, lalu klik Ubah password.')}catch(x){$('#er').textContent=x.message}}

