async function planBooking(b){if(!b.client_id)return 0;const td=tdy(),cd=(b.created_at||'').slice(0,10)||td,rows=[];
 FUB.forEach(([o,base,t,k])=>{const ref=base==='c'?cd:b.event_date;if(!ref)return;const due=addD(ref,o);if(due<td)return;rows.push({vendor_id:b.vendor_id,client_id:b.client_id,booking_id:b.id,ctx:'booking',code:`B-${base}${o}`,title:t,due_date:due,template_key:k})});
 if(!rows.length)return 0;const{error}=await sb.from('followups').insert(rows);if(error){console.warn(error.message);return 0}
 await sb.from('followups').update({status:'dilewati',note:'Otomatis: client sudah booking'}).eq('client_id',b.client_id).is('booking_id',null).eq('status','terjadwal').eq('ctx','lead');return rows.length}
async function fuAuto(){const[c,b,f]=await Promise.all(['clients','bookings','followups'].map(x=>qv(x).then(r=>r.data||[])));
 const hc=new Set(f.filter(x=>x.client_id&&!x.booking_id).map(x=>x.client_id)),hb=new Set(f.filter(x=>x.booking_id).map(x=>x.booking_id)),bc=new Set(b.filter(x=>x.status!=='cancelled').map(x=>x.client_id));
 for(const x of c)if(FUL[x.stage]&&!hc.has(x.id)&&!bc.has(x.id))await planLead(x);
 for(const x of b)if(x.status!=='cancelled'&&!hb.has(x.id))await planBooking(x)}
async function fup(){if(S.vendor!=='all'&&canW())await fuAuto();
 const[F,c,b,t]=await Promise.all(['followups','clients','bookings','wa_templates'].map(x=>qv(x).then(r=>r.data||[])));S.fu={F,c,b,t};
 main(`<div class=bar><h2>Follow-up Client</h2><input id=q placeholder="Cari client / tugas..."><select id=fx><option value=due>Hari ini & terlambat</option><option value=week>7 hari ke depan</option><option value=all>Semua terjadwal</option><option value=done>Selesai / dilewati</option></select><select id=fc><option value="">Lead & booking</option><option value=lead>Lead (belum booking)</option><option value=booking>Sudah booking</option></select>${canW()&&S.vendor!=='all'?`<button onclick="edit('followups')">+ Manual</button>`:''}</div><p><small>Rencana dibuat otomatis untuk lead dan booking baru (lead: sesuai tahap pipeline; booking: dari konfirmasi sampai pasca acara &amp; anniversary). Pindah tahap lead / booking baru akan menyusun ulang rencana. Isi pesan bisa diubah di menu Template WA.</small></p><div id=tb class=tw></div>`);
 const td=tdy(),w7=addD(td,7),draw=()=>{const s=$('#q').value.toLowerCase(),fx=$('#fx').value,fc=$('#fc').value,all=S.vendor==='all';
  const R=F.filter(x=>(fx==='done'?x.status!=='terjadwal':x.status==='terjadwal'&&(fx==='all'||(fx==='due'?x.due_date<=td:x.due_date<=w7)))&&(!fc||x.ctx===fc)&&((c.find(y=>y.id===x.client_id)?.name||'')+' '+(x.title||'')).toLowerCase().includes(s)).sort((a,b)=>a.due_date<b.due_date?-1:1);
  $('#tb').innerHTML=`<table><tr>${all?'<th>Vendor</th>':''}<th>Tanggal</th><th>Client</th><th>Konteks</th><th>Tugas</th><th>Channel</th><th></th></tr>${R.map(x=>{const cl=c.find(y=>y.id===x.client_id),bk=b.find(y=>y.id===x.booking_id),w=canW();
   return`<tr>${all?`<td>${esc(S.vendors.find(v=>v.id===x.vendor_id)?.name)}</td>`:''}<td>${x.status==='terjadwal'&&x.due_date<td?`<span class=err>${x.due_date}</span>`:x.due_date}</td><td>${cl?`<a class=lk data-tip="Buka ringkasan lengkap client ini" onclick="c360('${cl.id}')">${esc(cl.name)}</a>`:''}<br><small>${esc(cl?.phone)}</small></td><td>${bk?esc((bk.package||'Booking')+' · acara '+(bk.event_date||'-')):'Lead: '+esc(cl?.stage)}</td><td style="white-space:normal;min-width:200px">${esc(x.title)}${x.note?`<br><small>${esc(x.note)}</small>`:''}</td><td>${esc(x.channel)}</td><td>${!w?'':x.status==='terjadwal'?`<button onclick="fuWa('${x.id}')">Kirim WA</button> <button class=g onclick="fuDone('${x.id}')">Selesai</button> <button class=g onclick="fuSet('${x.id}',{due_date:addD(tdy(),3)})">Tunda 3 hr</button> <button class=g onclick="fuSet('${x.id}',{status:'dilewati'})">Lewati</button>`:`${x.status} <button class=g onclick="fuSet('${x.id}',{status:'terjadwal',done_at:null})">Buka lagi</button> `}${w?`<button class=g onclick="edit('followups','${x.id}')">Ubah</button>`:''}</td></tr>`}).join('')||'<tr><td colspan=7>Tidak ada follow-up 🎉</td></tr>'}</table>`};
 S.rows=F;$('#q').oninput=draw;$('#fx').onchange=draw;$('#fc').onchange=draw;await refs(E.followups);draw()}
async function fuSet(id,p){const{error}=await sb.from('followups').update(p).eq('id',id);error?alert(error.message):fup()}
function fuDone(id){const n=prompt('Catatan hasil follow-up (opsional)');if(n===null)return;fuSet(id,{status:'selesai',done_at:new Date().toISOString(),note:n||null})}
async function fuWa(id){const{F,c,b,t}=S.fu,f=F.find(x=>x.id===id),cl=c.find(x=>x.id===f.client_id),bk=b.find(x=>x.id===f.booking_id),tp=t.find(x=>x.key===f.template_key&&x.vendor_id===f.vendor_id),v=S.vendors.find(x=>x.id===f.vendor_id);
 if(!cl?.phone)return alert('Nomor WA client belum diisi');
 const V={nama:cl.name,vendor:v?.app_name||v?.name,tanggal:bk?.event_date||cl.desired_date||'',paket:bk?.package||''};
 open(waurl(cl.phone,tp?tp.body.replace(/\{\{(\w+)\}\}/g,(_,k)=>V[k]??''):`Halo Kak ${cl.name}, ${f.title}`));await fuSet(id,{status:'selesai',done_at:new Date().toISOString()})}
const MN=['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep','Okt','Nov','Des'],ymOf=d=>String(d||'').slice(0,7),shN=v=>Math.abs(v)>=1e6?(v/1e6).toFixed(1)+'jt':Math.abs(v)>=1e3?Math.round(v/1e3)+'rb':String(Math.round(v)),pct=(a,b)=>b?Math.round((a-b)/b*100)+'%':'-';
const addM=(ym,n)=>{const[y,m]=ym.split('-').map(Number);return new Date(Date.UTC(y,m-1+n,1)).toISOString().slice(0,7)},mLab=ym=>MN[+ym.slice(5)-1]+' '+ym.slice(2,4);
function chart(L,S2,type){const W=Math.max(L.length*(type==='bar'?S2.length*20+14:44)+56,340),st=(W-56)/L.length,all=S2.flatMap(s=>s.d),mx=Math.max(1,...all),mn=Math.min(0,...all),Y=v=>140-(v-mn)/(mx-mn)*100;
 let g=S2.map((s,k)=>`<rect x=${50+k*120} y=3 width=10 height=10 fill="${s.c}"/><text x=${64+k*120} y=12 font-size=10>${s.n}</text>`).join('')+`<line x1=48 y1=${Y(0)} x2=${W} y2=${Y(0)} stroke="#999"/><text x=2 y=${Y(mx)+3} font-size=9>${shN(mx)}</text>${mn<0?`<text x=2 y=${Y(mn)} font-size=9>${shN(mn)}</text>`:''}`;
 L.forEach((l,i)=>g+=`<text x=${50+i*st+st/2} y=158 font-size=9 text-anchor=middle>${l}</text>`);
 S2.forEach((s,k)=>{if(type==='bar'){const bw=(st-6)/S2.length;s.d.forEach((v,i)=>g+=`<rect x=${52+i*st+k*bw} y=${Math.min(Y(v),Y(0))} width=${Math.max(bw-1,1)} height=${Math.abs(Y(v)-Y(0))} fill="${s.c}"/>`)}else g+=`<polyline fill=none stroke="${s.c}" stroke-width=2 points="${s.d.map((v,i)=>`${50+i*st+st/2},${Y(v)}`).join(' ')}"/>`});
 return`<div class=tw style="padding:6px"><svg viewBox="0 0 ${W} 166" style="width:100%;min-width:${Math.min(W,600)}px;max-width:${Math.round(W*1.6)}px">${g}</svg></div>`}
const tb2=(h,r)=>`<div class=tw><table><tr>${h.map(x=>`<th>${x}</th>`).join('')}</tr>${r.map(a=>`<tr>${a.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')||`<tr><td colspan=${h.length}>-</td></tr>`}</table></div>`;
async function ana(){const[b0,p,i,x,c,tg]=await Promise.all(['bookings','payments','invoices','expenses','clients','targets'].map(t=>qv(t).then(r=>r.data||[]))),b=b0.filter(y=>y.status!=='cancelled');
 const td=tdy(),cm=td.slice(0,7),M=[...Array(12)].map((_,k)=>addM(cm,k-11)),inc=m=>sum(p.filter(y=>ymOf(y.paid_at)===m),'amount'),exo=m=>sum(x.filter(y=>ymOf(y.paid_at)===m),'amount'),nbk=m=>b.filter(y=>ymOf(y.created_at)===m).length;
 const I=M.map(inc),X=M.map(exo),LB=I.map((v,k)=>v-X[k]),PY=M.map(m=>inc(addM(m,-12))),NB=M.map(nbk);let cum=0;const CF=LB.map(v=>cum+=v),nz=b.filter(y=>y.total>0),ab=nz.length?sum(nz,'total')/nz.length:0;
 const bd=new Set(b.map(y=>y.event_date).filter(Boolean)),occ=(f,n)=>{let k=0;for(let j=0;j<n;j++)if(bd.has(addD(f,j)))k++;return Math.round(k/n*100)},dealN=c.filter(y=>y.stage==='deal').length;
 const rest=y=>y.amount-sum(p.filter(z=>z.invoice_id===y.id),'amount'),open_=i.filter(y=>y.status!=='paid'&&rest(y)>0);
 const F=[...Array(6)].map((_,k)=>addM(cm,k)),cmt={},pp={},prob={penawaran:[.5,1],meeting:[.25,2],inquiry:[.1,3]};
 open_.forEach(y=>{let m=ymOf(y.due_date)||cm;if(m<cm)m=cm;cmt[m]=(cmt[m]||0)+rest(y)});c.filter(y=>prob[y.stage]).forEach(y=>{const m=addM(cm,prob[y.stage][1]);pp[m]=(pp[m]||0)+prob[y.stage][0]*ab*.5});
 const n6=I.slice(6),sxy=n6.reduce((a,v,k)=>a+k*v,0),sy=sum(n6.map(v=>({a:v})),'a'),slope=(6*sxy-15*sy)/(6*55-225),icp=(sy-slope*15)/6,TR=F.map((_,k)=>Math.max(0,Math.round(icp+slope*(6+k)))),PJ=F.map(m=>Math.round((cmt[m]||0)+(pp[m]||0)));
 const pk={};b.forEach(y=>{const k=y.package||'(tanpa paket)',iv=i.filter(z=>z.booking_id===y.id),o=pk[k]??={n:0,om:0,rc:0,bx:0};o.n++;o.om+=Number(y.total||0);o.rc+=sum(p.filter(z=>iv.some(w=>w.id===z.invoice_id)),'amount');o.bx+=sum(x.filter(z=>z.booking_id===y.id),'amount')});
 const PK=Object.entries(pk).map(([k,o])=>[k,o.n,o.om,o.rc,o.bx,o.rc-o.bx,o.rc?Math.round((o.rc-o.bx)/o.rc*100)+'%':'-']).sort((a,b)=>b[5]-a[5]);
 const sr={};c.forEach(y=>{const k=y.source||'(tanpa sumber)',bk=b.filter(z=>z.client_id===y.id),o=sr[k]??={l:0,d:0,om:0};o.l++;if(y.stage==='deal'||bk.length)o.d++;o.om+=sum(bk,'total')});
 const SR=Object.entries(sr).map(([k,o])=>[k,o.l,o.d,Math.round(o.d/o.l*100)+'%',o.om,o.d?Math.round(o.om/o.d):0]).sort((a,b)=>b[4]-a[4]);
 const ag={'Belum jatuh tempo':[0,0],'1-30 hari':[0,0],'31-60 hari':[0,0],'>60 hari':[0,0]},pc2={};
 open_.forEach(y=>{const r=rest(y),d=y.due_date?Math.floor((new Date(td)-new Date(y.due_date))/864e5):0,k=d<=0?'Belum jatuh tempo':d<=30?'1-30 hari':d<=60?'31-60 hari':'>60 hari';ag[k][0]+=r;ag[k][1]++;const n=c.find(z=>z.id===y.client_id)?.name||'-';pc2[n]=(pc2[n]||0)+r});
 const SE=[...Array(12)].map((_,k)=>b.filter(y=>y.event_date&&+y.event_date.slice(5,7)===k+1).length),tm=tg.find(y=>y.ym===cm),yr=cm.slice(0,4),tY=sum(tg.filter(y=>y.ym.startsWith(yr)),'income'),aY=sum(p.filter(y=>ymOf(y.paid_at).startsWith(yr)),'amount');
 const prog=(a,t,f)=>t?`<div style="background:#eee;border-radius:6px;height:10px"><div style="width:${Math.min(100,a/t*100)}%;background:${BRAND()};height:10px;border-radius:6px"></div></div>${f(a)} dari ${f(t)} (${Math.round(a/t*100)}%)`:'<small>Belum ada target — isi di menu Target</small>',C=(l,v,s='')=>`<div class=card>${l}<b>${v}</b><small>${s}</small></div>`;
 S.anx=[...M.map((m,k)=>['Tren',mLab(m),I[k],X[k],LB[k]]),...F.map((m,k)=>['Proyeksi',mLab(m),Math.round(cmt[m]||0),Math.round(pp[m]||0),PJ[k]]),...PK.map(r=>['Paket',r[0],r[1],r[2],r[5]]),...SR.map(r=>['Sumber lead',r[0],r[1],r[2],r[4]]),...Object.entries(ag).map(([k,v])=>['Umur piutang',k,v[0],v[1],''])];
 main(`<div class=bar><h2>Analitik Manajemen</h2><button class=g onclick="csv('analitik',['Bagian','Keterangan','Nilai 1','Nilai 2','Nilai 3'],S.anx)">Ekspor Excel</button><button class=g onclick="pdf('Analitik',$('#an').innerHTML)">PDF</button></div><div id=an>
 <div class=cards>${C('Pemasukan bulan ini',rp(I[11]),'vs bulan lalu '+pct(I[11],I[10]))}${C('Laba bulan ini',rp(LB[11]),'vs tahun lalu (pemasukan) '+pct(I[11],PY[11]))}${C('Rata-rata nilai booking',rp(ab))}${C('Konversi lead → deal',(c.length?Math.round(dealN/c.length*100):0)+'%',dealN+' dari '+c.length+' client')}${C('Keterisian 90 hari ke depan',occ(td,90)+'%')}${C('Keterisian 12 bulan terakhir',occ(addD(td,-364),365)+'%')}${C('Total piutang',rp(sum(open_.map(y=>({a:rest(y)})),'a')),open_.length+' invoice')}${C('Proyeksi 3 bulan',rp(PJ[0]+PJ[1]+PJ[2]),'tagihan + pipeline')}</div>
 <h3>Target vs capaian</h3><div class=cards><div class=card>Pemasukan bulan ini${prog(I[11],tm?.income,rp)}</div><div class=card>Booking baru bulan ini${prog(NB[11],tm?.bookings,v=>v)}</div><div class=card>Pemasukan tahun ${yr} (YTD)${prog(aY,tY,rp)}</div></div>
 <h3>Tren 12 bulan</h3>${chart(M.map(mLab),[{n:'Pemasukan',c:BRAND(),d:I},{n:'Biaya',c:'#999999',d:X},{n:'Laba',c:'#22aa77',d:LB}],'line')}${tb2(['Bulan','Pemasukan','Biaya','Laba','Arus kas kumulatif','Pemasukan thn lalu','Δ YoY','Booking dibuat'],M.map((m,k)=>[mLab(m),rp(I[k]),rp(X[k]),rp(LB[k]),rp(CF[k]),rp(PY[k]),pct(I[k],PY[k]),NB[k]]))}
 <h3>Proyeksi pemasukan 6 bulan</h3>${chart(F.map(mLab),[{n:'Proyeksi (tagihan+pipeline)',c:BRAND(),d:PJ},{n:'Proyeksi tren',c:'#2277cc',d:TR}],'bar')}${tb2(['Bulan','Tagihan terjadwal (pasti)','Pipeline tertimbang','Total proyeksi','Proyeksi tren'],F.map((m,k)=>[mLab(m),rp(cmt[m]||0),rp(pp[m]||0),rp(PJ[k]),rp(TR[k])]))}<p><small>Tagihan terjadwal = sisa invoice menurut jatuh tempo (yang lewat dihitung bulan ini). Pipeline = probabilitas tahap (penawaran 50%, meeting 25%, inquiry 10%) × rata-rata nilai booking × 50% DP, jatuh 1–3 bulan ke depan. Proyeksi tren = garis tren (regresi linear) pemasukan 6 bulan terakhir. Ini perkiraan, bukan jaminan.</small></p>
 <h3>Per paket (mana yang paling untung)</h3>${tb2(['Paket','Booking','Omzet booking','Diterima','Biaya','Laba','Margin'],PK.map(r=>[esc(r[0]),r[1],rp(r[2]),rp(r[3]),rp(r[4]),rp(r[5]),r[6]]))}
 <h3>Per sumber lead</h3>${tb2(['Sumber','Lead','Deal','Konversi','Omzet','Rata-rata/deal'],SR.map(r=>[esc(r[0]),r[1],r[2],r[3],rp(r[4]),rp(r[5])]))}
 <h3>Umur piutang</h3>${tb2(['Kategori','Sisa tagihan','Jumlah invoice'],Object.entries(ag).map(([k,v])=>[k,rp(v[0]),v[1]]))}<h4>Piutang terbesar per client</h4>${tb2(['Client','Sisa tagihan'],Object.entries(pc2).sort((a,b)=>b[1]-a[1]).slice(0,10).map(([k,v])=>[esc(k),rp(v)]))}
 <h3>Musiman: jumlah acara per bulan (semua tahun)</h3>${chart(MN,[{n:'Acara',c:BRAND(),d:SE}],'bar')}</div>`)}

