const lc=s=>String(s||'').trim().toLowerCase(),tipFind=(a,t)=>{const k=lc(t),f=a.find(([p])=>k.startsWith(p));return f?f[1]:''};
const TIPON=()=>localStorage.getItem('tip_off')!=='1';
function ftip(k,n,t){const b=FT[k+'.'+n]||FT[n]||'',h=t.startsWith('ref:')?'Ketik untuk mencari lalu pilih dari daftar, atau klik untuk membuka daftar.':t.startsWith('combo:')?'Pilih dari daftar atau ketik sendiri.':t.startsWith('sel:')?'Pilih salah satu dari daftar.':t==='date'?'Klik ikon kalender atau ketik tanggal.':t==='dt'?'Isi tanggal dan jam.':t==='rp'?'Isi angka saja (rupiah), tanpa titik/koma.':t==='num'?'Isi angka.':t==='file'?'Klik untuk memilih file.':'';return b&&h?b+'\n'+h:b||h}
let tipE=null,tipT=null;
function tipShow(el){const t=el.dataset.tip;if(!t||!TIPON())return;if(!tipE){tipE=document.createElement('div');tipE.id='tip'}(document.querySelector('dialog[open]')||document.body).appendChild(tipE);tipE.textContent=t;tipE.style.display='block';
 const r=el.getBoundingClientRect(),w=tipE.offsetWidth,h=tipE.offsetHeight;let x=Math.min(Math.max(8,r.left),innerWidth-w-8),y=r.bottom+8;if(y+h>innerHeight-8)y=Math.max(8,r.top-h-8);tipE.style.left=x+'px';tipE.style.top=y+'px'}
const tipHide=()=>{if(tipE)tipE.style.display='none'},tipEl=e=>e.target.closest?.('[data-tip]:not([data-tip=""])');
document.addEventListener('mouseover',e=>{const el=tipEl(e);el?tipShow(el):tipHide()});document.addEventListener('focusin',e=>{const el=tipEl(e);el?tipShow(el):tipHide()});
document.addEventListener('mouseout',e=>{if(!e.relatedTarget)tipHide()});document.addEventListener('click',()=>setTimeout(tipHide,0));addEventListener('scroll',tipHide,true);
document.addEventListener('touchstart',e=>{const el=tipEl(e);clearTimeout(tipT);if(el)tipT=setTimeout(()=>tipShow(el),450)},{passive:true});document.addEventListener('touchend',()=>{clearTimeout(tipT);setTimeout(tipHide,2500)});
function tipToggle(){const on=TIPON();localStorage.setItem('tip_off',on?'1':'0');$('#tg').textContent='💡 Bantuan: '+(on?'OFF':'ON');tipHide()}
function applyTips(){document.querySelectorAll('nav a[data-p]').forEach(a=>{if(a.dataset.tip===undefined)a.dataset.tip=NAVT[a.dataset.p]||''});
 document.querySelectorAll('button').forEach(b=>{if(b.dataset.tip===undefined)b.dataset.tip=BTN[lc(b.textContent)]||tipFind(BTP,b.textContent)});
 document.querySelectorAll('input[id],select[id],textarea[id]').forEach(e=>{if(e.dataset.tip===undefined)e.dataset.tip=(e.type==='file'&&e.id==='rf'?'File JSON hasil menu Backup Data.':e.type==='date'&&e.id==='rf'?IDT.rf:IDT[e.id])||''});
 document.querySelectorAll('label').forEach(l=>{if(l.dataset.tip===undefined)l.dataset.tip=tipFind(LBL,l.firstChild?.textContent||'')});
 document.querySelectorAll('.card').forEach(c=>{if(c.dataset.tip===undefined)c.dataset.tip=tipFind(CARD,c.firstChild?.textContent||'')});
 const hs=document.querySelector('header select');if(hs&&hs.dataset.tip===undefined)hs.dataset.tip='Pilih vendor yang datanya ingin dilihat/diisi. Semua vendor hanya untuk melihat gabungan (tidak bisa menambah data).'}
new MutationObserver(()=>{clearTimeout(S.at);S.at=setTimeout(applyTips,40)}).observe(document.body,{childList:true,subtree:true});applyTips();
