const hm=t=>esc(String(t).replace(/@SB@/g,SBU)).replace(/\*\*(.+?)\*\*/g,'<b>$1</b>').replace(/\[\[(\w+)\|([^\]]+)\]\]/g,(_,p,l)=>`<a class=hl data-tip="Buka halaman: ${l}" onclick="go('${p}')">${l} →</a>`).replace(/\{\{(https?:[^|]+)\|([^}]+)\}\}/g,(_,u,l)=>`<a class=hl href="${u}" target=_blank rel=noopener data-tip="Membuka situs luar di tab baru">${l} ↗</a>`);
