const HELP=[
{id:'peran',i:'👥',t:'Peran dan hak akses',r:'all',d:"Menu yang Anda lihat menyesuaikan peran akun.",s:["**Admin** (pemilik platform): kelola semua vendor, masa aktif, tagihan langganan, migrasi, audit.","**Owner** (pemilik vendor): semua fitur vendornya termasuk hapus data, Pengguna, Pengaturan, Backup, Audit Log.","**Staff**: baca dan tulis data; tidak bisa menghapus atau mengatur pengguna.","**Guest/Visitor**: hanya melihat."],n:["💡 Owner bisa membatasi per orang dan per menu (Tidak boleh lihat / Baca saja / Baca & tulis) lewat tombol **Akses modul** di [[users|menu Pengguna]]."]},
{id:'dash',i:'🏠',t:'Dashboard',r:'all',d:"Ringkasan harian vendor. Arahkan kursor ke tiap kartu untuk melihat artinya.",s:["Lihat **Booking aktif**, **Acara 30 hari**, **Tagihan belum terbayar**, dan **Pemasukan bulan ini**.","Kartu **Pengingat tertunda** dan **Follow-up hari ini** menunjukkan pekerjaan yang perlu dikerjakan sekarang.","Tabel di bawah menampilkan acara 30 hari ke depan."],g:"[[dashboard|Buka Dashboard]] [[reminders|Pengingat]] [[fup|Follow-up]]"},
{id:'client',i:'🧑‍🤝‍🧑',t:'Client dan Portal Client',r:'all',d:"Database client dan calon client. Semua data lain (booking, invoice, follow-up) terhubung ke client.",s:["Klik **+ Tambah**, isi Nama dan WhatsApp (08xx boleh). Pilih **Sumber lead** dari daftar atau ketik sendiri.","Tahap pipeline default **inquiry**. Rencana follow-up otomatis dibuat untuk lead baru.","Tombol **Portal** membuat link hanya-baca untuk client (tagihan, sisa bayar, jadwal, hasil). Kirim lewat WA; klik **Buat ulang** jika link bocor.","Untuk data banyak, pakai [[import|Impor CSV]]."],n:["💡 Di kolom lain yang meminta Client, cukup ketik sebagian nama lalu pilih dari daftar."],g:"[[clients|Buka Client]] [[import|Impor Data]]"},
{id:'pipe',i:'🧲',t:'Pipeline lead',r:'all',d:"Papan lead per tahap sampai deal, plus konversi per sumber.",s:["Geser lead dengan ◀ ▶ sesuai perkembangan: inquiry → meeting → penawaran → deal atau batal.","Setiap pindah tahap, rencana follow-up lama dihentikan dan disusun ulang untuk tahap baru.","Lihat persen konversi di atas dan tabel konversi per sumber di bawah."],g:"[[pipeline|Buka Pipeline]] [[analytics|Analitik per sumber]]"},
{id:'booking',i:'📋',t:'Booking, Acara, Meeting, dan Kalender',r:'all',d:"Catat pesanan, hari-H, dan janji bertemu; semuanya tampil di Kalender.",s:["**Booking**: pilih Client, **Paket** (dari daftar atau ketik), tanggal acara, total. Bila memilih dari daftar paket, harga terisi otomatis.","Saat menyimpan, aplikasi **memperingatkan** jika tanggal sudah melewati kuota atau diblokir; Anda boleh tetap menyimpan.","**Acara** dan **Meeting** dicatat di menunya masing-masing; meeting muncul di Pengingat 2 hari sebelumnya.","**Blokir Tanggal** untuk libur atau penuh. **Kalender** menggabungkan acara, booking, dan meeting."],n:["⚠ Status **cancelled** tidak dihitung di laporan dan analitik."],g:"[[bookings|Booking]] [[events|Acara]] [[meetings|Meeting]] [[blocked_dates|Blokir Tanggal]] [[calendar|Kalender]]"},
{id:'paket',i:'🎁',t:'Paket dan Penawaran',r:'all',d:"Daftar harga baku dan penawaran siap kirim.",s:["Di **Paket**, tambah nama, isi, dan harga. Paket aktif muncul di pilihan Booking dan form publik.","Di **Penawaran**, pilih Client dan Paket (harga terisi), isi diskon, biaya tambahan, pajak bila perlu; total dihitung otomatis.","Klik **PDF** untuk mencetak penawaran dengan logo, rekening, dan QRIS.","Bila disetujui, klik **Jadi Booking**: aplikasi membuat booking + invoice DP dengan persentase yang Anda isi."],g:"[[packages|Paket]] [[quotes|Penawaran]]"},
{id:'invoice',i:'🧾',t:'Invoice, Cicilan, Pembayaran, dan Kwitansi',r:'all',d:"Alur tagihan sampai lunas.",s:["**Invoice**: nomor otomatis **INV-YYMM-001** (bisa diubah), tanggal terbit default hari ini, isi jatuh tempo. Rincian diskon, biaya tambahan, dan pajak bersifat opsional.","Di **Booking**, tombol **Cicilan** membuat beberapa invoice sekaligus (mis. 50,30,20). Jatuh tempo tersebar sampai 7 hari sebelum acara.","**Pembayaran**: pilih invoice, isi jumlah; nomor kwitansi otomatis **KW-YYMM-001**. Unggah bukti transfer (maks 2 MB) bila ada.","Tombol **Kwitansi** mencetak tanda terima; tombol **PDF** di Invoice mencetak invoice. Pilih Simpan sebagai PDF di dialog cetak."],n:["💡 Sisa tagihan = total invoice dikurangi semua pembayaran. Ubah status invoice menjadi paid saat lunas agar tidak muncul di Pengingat."],g:"[[invoices|Invoice]] [[payments|Pembayaran]] [[bookings|Booking (tombol Cicilan)]]"},
{id:'wa',i:'💬',t:'WhatsApp: Kirim WA, Template, Pengingat, Follow-up',r:'all',d:"Aplikasi menyiapkan pesan; Anda menekan kirim di WhatsApp (tidak ada kirim otomatis tanpa WhatsApp Business API).",s:["**Kirim WA**: pilih Client dan Invoice; template otomatis menyesuaikan (DP, pelunasan, terima kasih). Edit pesan lalu klik **Buka WhatsApp**.","**Pengingat**: invoice jatuh tempo (3 hari sebelum/lewat), meeting 2 hari, acara 7 hari, dan permintaan ulasan. Klik **Kirim WA** atau **Lewati**.","**Follow-up**: rencana otomatis. Lead: sapa, tanya kabar, tawarkan meeting, penawaran, terakhir, reaktivasi. Booking: terima kasih, cek DP, H-60, H-30, H-14, H-7, H-1, pasca acara, kirim hasil, H+30, anniversary.","Isi pesan bisa diubah di **Template WA**. Variabel seperti {{nama}} dan {{tanggal}} terisi otomatis."],n:["⚠ Nomor WA client wajib diisi di data Client agar tombol Kirim WA bekerja."],g:"[[wa|Kirim WA]] [[reminders|Pengingat]] [[fup|Follow-up]] [[wa_templates|Template WA]]"},
{id:'ttd',i:'✍️',t:'Kerjasama dan tanda tangan digital',r:'all',d:"Simpan perjanjian dengan mitra dan minta tanda tangan online.",s:["Tambah perjanjian di **Kerjasama** (mitra, jenis, ketentuan).","Klik **Link TTD** lalu kirim ke mitra. Mitra membaca ketentuan, mengisi nama, menggambar tanda tangan di layar.","Setelah ditandatangani, tombol berubah menjadi **✓ Lihat TTD**."],n:["⚠ Mengubah isi ketentuan setelah ditandatangani menghapus tanda tangan; harus diulang. Untuk kontrak bernilai besar, konsultasikan ke ahli hukum."],g:"[[partnerships|Buka Kerjasama]]"},
{id:'output',i:'📦',t:'Output, Matriks Kebutuhan, dan Tim',r:'all',d:"Pantau pekerjaan setelah deal.",s:["**Output**: hasil yang dijanjikan (album, video), deadline, status, link hasil; link tampil di portal client.","**Matriks Kebutuhan**: pilih booking lalu klik **Muat matriks kategori** untuk mengisi daftar standar sesuai kategori vendor.","**Tim & Honor**: tugaskan crew ke acara, atur honor, kirim detail via tombol **WA**. Aplikasi memperingatkan jika crew bentrok. Status **dibayar** otomatis jadi pengeluaran honor."],g:"[[deliverables|Output]] [[requirements|Matriks Kebutuhan]] [[assignments|Tim & Honor]]"},
{id:'uang',i:'💰',t:'Pengeluaran dan Laba Rugi',r:'all',d:"Hitung untung per acara.",s:["Catat biaya di **Pengeluaran**; pilih Booking agar masuk perhitungan acara itu (kosong = biaya umum).","Buka **Laba Rugi** untuk melihat pemasukan, biaya, dan laba per acara; bisa diekspor Excel/PDF."],g:"[[expenses|Pengeluaran]] [[pnl|Laba Rugi]]"},
{id:'lapor',i:'📊',t:'Laporan, Analitik, dan Target',r:'all',d:"Dari pemantauan sampai keputusan bisnis.",s:["**Laporan**: filter tanggal untuk pemasukan per bulan, booking per status, dan piutang per client.","**Analitik**: tren 12 bulan (YoY dan arus kas), proyeksi 6 bulan, per paket (untung/margin), per sumber lead, umur piutang, musiman, keterisian tanggal.","**Target**: isi target pemasukan dan booking baru per bulan (format bulan 2026-12); capaian tampil di Analitik."],n:["💡 Proyeksi adalah perkiraan; makin rutin data invoice dan pipeline diperbarui, makin akurat. Metodenya dijelaskan di bawah tabel proyeksi."],g:"[[reports|Laporan]] [[analytics|Analitik]] [[targets|Target]]"},
{id:'ulasan',i:'⭐',t:'Ulasan client',r:'all',d:"Kumpulkan penilaian dan tampilkan sebagai bukti sosial.",s:["Klik **Ulasan** di baris Booking atau ikuti permintaan di Pengingat; link ulasan dikirim lewat WA.","Client memberi bintang 1-5 dan komentar tanpa login.","Di menu **Ulasan**, atur kolom Tampil di form booking: ulasan bintang 4-5 yang berkomentar tampil di form publik."],g:"[[reviews|Buka Ulasan]]"},
{id:'set',i:'⚙️',t:'Pengaturan vendor dan Form booking publik',r:'owner',d:"Identitas dan aturan dasar vendor.",s:["Isi **Nama aplikasi** dan unggah **Logo** (maks 512 KB, 600x600 px).","Isi **Rekening** dan unggah **QRIS** (maks 512 KB, 1200x1200 px); keduanya tercetak di invoice dan penawaran.","Atur **Kuota acara per tanggal** untuk peringatan bentrok.","Isi **Alamat form booking** (mis. studio-rina) lalu bagikan link /book.html?v=studio-rina di Instagram atau WA. Calon client masuk sebagai lead tahap inquiry (sumber: Form online)."],g:"[[branding|Buka Pengaturan]]"},
{id:'user',i:'🔐',t:'Pengguna dan Akses modul',r:'owner',d:"Kelola akun staf vendor.",s:["Isi nama, email, password awal, dan peran lalu klik **Buat akun** (butuh aplikasi aktif di Netlify).","Ubah peran, izin tulis, atau nonaktifkan lewat kolom di tabel.","Tombol **Akses modul** membatasi menu per orang: Tidak boleh lihat / Baca saja / Baca & tulis."],n:["⚠ Saat tes lokal tanpa Netlify, akun dibuat manual lewat {{@SB@/auth/users|Supabase → Authentication → Users}} lalu didaftarkan ke tabel profiles dengan SQL."],g:"[[users|Buka Pengguna]]"},
{id:'data',i:'💾',t:'Impor, Backup, dan Pulihkan',r:'owner',d:"Keamanan dan perpindahan data.",s:["**Impor Data**: pilih jenis, unduh template, isi di Excel, Save As CSV, unggah, lihat pratinjau, klik **Impor sekarang**.","**Backup Data**: unduh JSON seluruh data vendor secara berkala; halaman menunjukkan backup terakhir.","**Pulihkan Backup**: pilih file JSON. Mode aman menambah yang belum ada; mode timpa mengembalikan data ber-ID sama ke kondisi backup."],n:["💡 Unduh backup sebelum impor besar atau pemulihan."],g:"[[import|Impor]] [[backup|Backup]] [[restore|Pulihkan]]"},
{id:'gcal',i:'📅',t:'Google Kalender dan PWA',r:'all',d:"Bawa jadwal dan aplikasi ke HP.",s:["Di **Kalender**, klik **Sinkron Google Kalender**, salin link, lalu buka {{https://calendar.google.com/calendar/r/settings/addbyurl|Google Kalender → Dari URL}} dan tempel. Satu arah, diperbarui Google tiap sekitar 12-24 jam.","**Pasang aplikasi** (PWA): klik tombol di header (Chrome/Android) atau di iPhone Safari → Bagikan → Tambah ke Layar Utama.","Saat offline, data yang terakhir dibuka tetap bisa dilihat; mengubah data butuh internet."],g:"[[calendar|Buka Kalender]]"},
{id:'admin',i:'🛠️',t:'Khusus Admin: Vendor, Langganan, Platform',r:'admin',d:"Mengelola bisnis platform.",s:["**Vendor**: tambah vendor; atur Masa aktif: lifetime, duration (hari), atau until_date. Status inactive memblokir akses tanpa menghapus data.","**Pengguna**: pilih vendor di dropdown atas lalu buat akun Owner.","**Tagihan Vendor**: buat tagihan; ubah status ke paid dan masa aktif otomatis diperpanjang sampai akhir periode.","**Dashboard Platform**: vendor yang segera habis, tombol **Kirim WA** dan **Perpanjang**.","**Matriks Kategori**: standar kebutuhan per kategori."],g:"[[vendors|Vendor]] [[users|Pengguna]] [[vendor_bills|Tagihan Vendor]] [[platform|Dashboard Platform]] [[category_matrix|Matriks Kategori]]"},
{id:'sys',i:'🧰',t:'Khusus Admin: Audit Log dan Migrasi',r:'admin',d:"Keamanan dan pindah server.",s:["**Audit Log**: siapa mengubah apa dan kapan; tidak bisa diubah dari aplikasi.","**Migrasi Data**: Ekspor Migrasi Penuh menghasilkan ZIP (semua tabel, pengguna tanpa password, file). Di Supabase baru jalankan SQL, buat admin, lalu Mulai impor dengan password sementara.","Cek dan kelola project di {{@SB@|Supabase Dashboard}}, {{@SB@/sql/new|SQL Editor}}, dan {{https://app.netlify.com/|Netlify}}."],g:"[[audit|Audit Log]] [[migrate|Migrasi Data]] [[app_releases|Riwayat Versi]]"},
{id:'istilah',i:'📘',t:'Daftar istilah dan status',r:'all',d:"Arti status yang sering muncul.",s:["Booking: **inquiry** baru tanya, **booked** deal, **dp_paid** DP masuk, **paid_off** lunas, **done** selesai, **cancelled** batal.","Invoice: **unpaid**, **partial**, **paid**. Tipe: **dp**, **pelunasan**, **lainnya**.","Pipeline: **inquiry**, **meeting**, **penawaran**, **deal**, **batal**.","Follow-up: **terjadwal**, **selesai**, **dilewati**. H-30 artinya 30 hari sebelum acara; H+3 tiga hari sesudah.","Piutang: sisa tagihan yang belum dibayar."]},
{id:'faq',i:'🆘',t:'Pemecahan masalah',r:'all',d:"Masalah yang sering terjadi dan solusinya.",s:["**Invalid API key / 401 saat login**: pastikan URL dan kunci di config.js dari project Supabase yang sama ({{@SB@/settings/api-keys|Settings → API Keys}}); coba jendela Incognito (ekstensi browser kadang mengganggu).","**Data tidak muncul**: akun vendor mungkin kedaluwarsa/nonaktif, atau akses modul Anda diatur Tidak boleh lihat. Hubungi Owner/Admin.","**Tombol Kirim WA tidak jalan**: nomor WA client belum diisi.","**Pilihan Client kosong**: tambah dulu di [[clients|menu Client]].","**Tampilan lama setelah update**: tekan Ctrl+Shift+R.","**Tooltip mengganggu**: matikan lewat tombol 💡 Bantuan di header."]}];
function helpPage(){const adm=isA(),CK=adm?CK_A:CK_V,sv=JSON.parse(localStorage.getItem('hchk_'+(adm?'a':'v'))||'[]'),ok=x=>x.r==='all'||(x.r==='owner'&&canD())||(x.r==='admin'&&adm),H=HELP.filter(ok);
 main(`<div class=hero><h2>📖 Cara Pakai ${esc(vn())}</h2><p>Panduan lengkap. Klik tombol berwarna merah muda (→) untuk langsung membuka halaman yang dibahas. Arahkan kursor ke menu, tombol, dan isian untuk melihat penjelasan singkatnya.</p><input id=hq placeholder="🔎 Cari topik (mis. invoice, WA, backup)..." oninput=helpQ()></div>
 <h3>✅ Checklist mulai cepat <small id=hp></small></h3><div class=pb><div id=hpb style="width:0"></div></div><div class=chk>${CK.map((t,i)=>`<label class=ck><input type=checkbox ${sv.includes(i)?'checked':''} onchange="hck(${i},this.checked)"><span>${hm(t)}</span></label>`).join('')}</div>
 <h3>🧭 Daftar isi</h3><div class=toc>${H.map(x=>`<a onclick="hopen('${x.id}')" data-tip="Buka bagian ini">${x.i} ${x.t}</a>`).join('')}</div>
 ${H.map(x=>`<details id="h_${x.id}" class=hs><summary>${x.i} ${x.t}</summary><div class=hb><p>${hm(x.d)}</p>${x.s?`<ol class=stp>${x.s.map(l=>`<li>${hm(l)}</li>`).join('')}</ol>`:''}${(x.n||[]).map(n=>`<div class=nt>${hm(n)}</div>`).join('')}${x.g?`<p class=gl><b>Langsung ke:</b> ${hm(x.g)}</p>`:''}</div></details>`).join('')}`);hprog()}
function hprog(){const adm=isA(),n=CK_V.length,t=adm?CK_A.length:n,c=JSON.parse(localStorage.getItem('hchk_'+(adm?'a':'v'))||'[]').length;$('#hp').textContent=`(${c}/${t} selesai)`;$('#hpb').style.width=Math.round(c/t*100)+'%'}
function hck(i,on){const k='hchk_'+(isA()?'a':'v'),a=new Set(JSON.parse(localStorage.getItem(k)||'[]'));on?a.add(i):a.delete(i);localStorage.setItem(k,JSON.stringify([...a]));hprog()}
function hopen(id){const d=$('#h_'+id);d.open=true;d.scrollIntoView({behavior:'smooth',block:'start'})}
function helpQ(){const q=lc($('#hq').value);document.querySelectorAll('.hs').forEach(d=>{const m=!q||d.textContent.toLowerCase().includes(q);d.style.display=m?'':'none';if(q)d.open=m})}

// ===== KETERKAITAN DATA =====
const refLink=(k,v)=>{const l=esc(S.ref[k]?.[v]);if(!v||!l)return l||'';const f={clients:'c360',bookings:'b360',invoices:'i360'}[k];return f?`<a class=lk data-tip="Klik untuk membuka ringkasan lengkap dan data terkait" onclick="${f}('${v}')">${l}</a>`:l};
const grp=(a,k)=>{const o={};a.forEach(x=>(o[x[k]]??=[]).push(x));return o},sc=id=>document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'});
const chp=(fn,id,sec,t,c,tip)=>`<span class="chip ${c}" data-tip="${esc(tip||CHIPTIP[sec]||'Klik untuk membuka rincian')}" onclick="${fn}('${id}','${sec}')">${esc(t)}</span>`;
const stc=v=>`<span class="chip ${['paid','selesai','terkirim','done','booked','dp_paid','paid_off','deal','aktif','terisi','dikonfirmasi','dibayar','diterima'].includes(v)?'ok':['cancelled','batal','ditolak','nonaktif','dilewati'].includes(v)?'bad':'warn'}">${esc(v)}</span>`;
BTN.detail="Membuka ringkasan lengkap data ini beserta semua data terkait (booking, invoice, pembayaran, acara, dll.).";
E.clients.rel=async rows=>{const[b,ev,m,i,p,q,f]=await Promise.all(['bookings','events','meetings','invoices','payments','quotes','followups'].map(t=>qv(t).then(r=>r.data||[])));
 const B=grp(b.filter(x=>x.status!=='cancelled'),'client_id'),EV=grp(ev,'client_id'),M=grp(m,'client_id'),I=grp(i,'client_id'),Q=grp(q,'client_id'),F=grp(f.filter(x=>x.status==='terjadwal'),'client_id'),P={};p.forEach(x=>P[x.invoice_id]=(P[x.invoice_id]||0)+Number(x.amount||0));
 S.relS={};const o={};rows.forEach(c=>{const bb=B[c.id]||[],ii=I[c.id]||[],unp=ii.filter(x=>x.status!=='paid'&&x.amount-(P[x.id]||0)>0).length,pd=ii.filter(x=>(P[x.id]||0)>0).length,mm=(M[c.id]||[]).filter(x=>x.status==='dijadwalkan').length,ea=(EV[c.id]||[]).length,k=(s,t,cl,tp)=>chp('c360',c.id,s,t,cl,tp);S.relS[c.id]={f:[bb.length?'booking':'nobooking',...(bb.length&&!ii.length?['bookingnoinv']:[]),...(unp?['invunpaid']:ii.length?['invpaid']:[]),...(!pd?['nopay']:[]),...(mm?['meeting']:[]),...(F[c.id]?['fu']:[]),...(Q[c.id]?['quote']:[])],g:!bb.length?GO[0]:!ii.length?GO[1]:unp?GO[2]:GO[3]};
  o[c.id]=k('s_booking',bb.length?`📋 ${bb.length} booking`:'📋 Belum ada booking',bb.length?'ok':'no')+k('s_invoice',ii.length?`🧾 ${ii.length} invoice${unp?` (${unp} belum lunas)`:' (lunas)'}`:bb.length?'⚠ Booking belum ada invoice':'🧾 Belum ada invoice',ii.length?(unp?'warn':'ok'):bb.length?'bad':'no')+k('s_bayar',pd?`💰 ${pd} invoice sudah dibayar`:'💰 Belum ada pembayaran',pd?'ok':ii.length?'warn':'no')+k('s_acara',ea?`📅 ${ea} acara`:'📅 Belum ada acara',ea?'ok':'no')+k('s_meeting',mm?`🤝 ${mm} meeting terjadwal`:'🤝 Tidak ada meeting terjadwal',mm?'ok':'no')+(Q[c.id]?k('s_quote',`📄 ${Q[c.id].length} penawaran`,'ok'):'')+(F[c.id]?k('s_fu',`🔔 ${F[c.id].length} follow-up`,'warn'):'')});return o};
E.bookings.rel=async rows=>{const[i,p,ev,d,a,x,f,q]=await Promise.all(['invoices','payments','events','deliverables','assignments','expenses','followups','quotes'].map(t=>qv(t).then(r=>r.data||[])));
 const I=grp(i,'booking_id'),EV=grp(ev,'booking_id'),D=grp(d,'booking_id'),A=grp(a,'booking_id'),X=grp(x,'booking_id'),F=grp(f.filter(y=>y.status==='terjadwal'),'booking_id'),P={};p.forEach(y=>P[y.invoice_id]=(P[y.invoice_id]||0)+Number(y.amount||0));
 const o={};rows.forEach(b=>{const ii=I[b.id]||[],tot=sum(ii,'amount'),pd=ii.reduce((n,y)=>n+(P[y.id]||0),0),k=(s,t,cl)=>chp('b360',b.id,s,t,cl);
  o[b.id]=k('s_invoice',ii.length?`🧾 ${ii.length} invoice`:'⚠ Belum ada invoice',ii.length?'ok':'bad')+(ii.length?k('s_bayar',tot>0&&pd>=tot?'💰 Lunas':pd>0?`💰 Terbayar ${rp(pd)} dari ${rp(tot)}`:'💰 Belum ada pembayaran',tot>0&&pd>=tot?'ok':'warn'):'')+k('s_acara',(EV[b.id]||[]).length?`📅 ${EV[b.id].length} acara`:'📅 Acara belum dicatat',(EV[b.id]||[]).length?'ok':'no')+k('s_output',(D[b.id]||[]).length?`📦 ${D[b.id].length} output`:'📦 Belum ada output',(D[b.id]||[]).length?'ok':'no')+k('s_tim',(A[b.id]||[]).length?`👥 ${A[b.id].length} crew`:'👥 Belum ada crew',(A[b.id]||[]).length?'ok':'no')+((X[b.id]||[]).length?k('s_biaya',`💸 Biaya ${rp(sum(X[b.id],'amount'))}`,'ok'):'')+(F[b.id]?k('s_fu',`🔔 ${F[b.id].length} follow-up`,'warn'):'')});return o};
E.invoices.rel=async rows=>{const p=(await qv('payments')).data||[],P=grp(p,'invoice_id'),o={};rows.forEach(v=>{const n=(P[v.id]||[]).length,pd=sum(P[v.id]||[],'amount'),r=v.amount-pd;
 o[v.id]=chp('i360',v.id,'',n?`💰 ${n} pembayaran · terbayar ${rp(pd)}`:'💰 Belum ada pembayaran',n?'ok':'warn')+chp('i360',v.id,'',r>0?`Sisa ${rp(r)}`:'Lunas',r>0?'warn':'ok')});return o};
E.quotes.rel=async rows=>{const o={};rows.forEach(q=>{o[q.id]=q.booking_id?chp('b360',q.booking_id,'','🔗 Sudah jadi booking','ok','Klik untuk membuka booking hasil penawaran ini'):'<span class="chip no">Belum jadi booking</span>'});return o};
