function brand2(){const v=curV();if(!v)return main('<p>Pilih vendor terlebih dahulu.</p>');const x=k=>esc(v[k]);
 main(`<h2>⚙️ Pengaturan Vendor</h2><div class=form><h3 style="margin-top:0">Identitas & kop surat dokumen</h3><div class=fg><label>Nama aplikasi / usaha<input id=bn2 value="${esc(v.app_name||v.name)}"></label><label>Logo (maks 512 KB, 600x600 px)<input id=bl type=file accept="image/png,image/jpeg,image/webp"></label><label>Alamat<input id=va value="${x('address')}"></label><label>Email<input id=ve value="${x('email')}"></label><label>Website / Instagram<input id=vw value="${x('website')}"></label><label>NPWP (opsional)<input id=vn value="${x('npwp')}"></label><label>Nama penanda tangan<input id=vs value="${x('signer_name')}"></label><label>Jabatan penanda tangan<input id=vt value="${x('signer_title')}"></label></div>
 <h3>Warna tema</h3><div class=fg><label>Warna utama (tombol, header, judul, dokumen cetak)<input id=vc type=color value="${esc(v.theme_color||'#9d4a62')}" oninput="applyTheme(this.value)" style="height:44px;padding:3px"></label><div class=lb><b>Pilihan cepat</b><div>${THEMES.map(([n,c])=>`<span class=chip style="background:${c};color:#fff" data-tip="Pakai warna ${n} (pratinjau langsung; klik Simpan untuk menetapkan)" onclick="pickTheme('${c}')">${n}</span>`).join('')}<span class=chip style="background:#fff;border:1px solid #ccc;color:#444" onclick="pickTheme('#9d4a62')" data-tip="Kembali ke warna bawaan aplikasi">↺ Bawaan</span></div></div></div><h3>Pembayaran</h3><div class=fg><label>Rekening untuk invoice<textarea id=bk rows=3>${x('bank_info')}</textarea></label><label>QRIS (maks 512 KB, 1200x1200 px)<input id=qr type=file accept="image/png,image/jpeg,image/webp"></label></div>
 <h3>Operasional</h3><div class=fg><label>Kuota acara per tanggal<input id=cp type=number min=1 value="${v.booking_cap||1}"></label><label>Alamat form booking (a-z, 0-9, strip)<input id=sl value="${x('slug')}"></label></div>${v.slug?`<p>Form publik: <a href="/book.html?v=${x('slug')}" target=_blank>${BASE()}/book.html?v=${x('slug')}</a></p>`:''}<button onclick=saveBrand2()>Simpan</button><p id=er class=err></p></div>`)}
async function saveBrand2(){const v=curV();try{const f=$('#bl').files[0],q=$('#qr').files[0],logo=f?await upLogo(v.id,f):v.logo_url,qr=q?await upLogo(v.id,q,1200):v.qris_url,sl=$('#sl').value.trim().toLowerCase()||null;if(sl&&!/^[a-z0-9-]{3,40}$/.test(sl))throw Error('Alamat form: 3-40 karakter a-z, 0-9, strip');
 let r=await sb.rpc('update_branding',{p_vendor:v.id,p_app:$('#bn2').value,p_logo:logo});if(r.error)throw r.error;
 r=await sb.rpc('set_vendor_settings',{p_vendor:v.id,p_cap:+$('#cp').value||1,p_slug:sl,p_bank:$('#bk').value,p_qris:qr});if(r.error)throw r.error;
 r=await sb.rpc('set_vendor_profile',{p_vendor:v.id,p_address:$('#va').value,p_email:$('#ve').value,p_website:$('#vw').value,p_npwp:$('#vn').value,p_signer:$('#vs').value,p_signer_title:$('#vt').value});if(r.error)throw Error(r.error.message+' (pastikan migration_1.13.0.sql sudah dijalankan)');const col=$('#vc').value;if(lum(col)>.35)throw Error('Warna terlalu terang: teks putih pada tombol dan header sulit dibaca. Pilih warna yang lebih gelap.');r=await sb.rpc('set_vendor_theme',{p_vendor:v.id,p_color:col});if(r.error)throw Error(r.error.message+' (pastikan migration_1.14.0.sql sudah dijalankan)');
 S.vendors=(await sb.from('vendors').select('*').order('name')).data;const p=S.p;shell();go(p)}catch(x){$('#er').textContent=String(x.message).includes('duplicate')?'Alamat form sudah dipakai':x.message}}
