const THEMES=[['Rose','#9d4a62'],['Marun','#8e2a3a'],['Zamrud','#1f7a5a'],['Biru laut','#1f5f99'],['Ungu','#6b4fa0'],['Emas','#a0722a'],['Teal','#167d85'],['Arang','#3b4252']];
const hx=h=>[1,3,5].map(i=>parseInt(h.slice(i,i+2),16)),mixc=(a,b,t)=>'#'+hx(a).map((x,i)=>Math.round(x*(1-t)+hx(b)[i]*t).toString(16).padStart(2,'0')).join(''),lum=h=>{const[r,g,b]=hx(h).map(v=>{v/=255;return v<=.03928?v/12.92:Math.pow((v+.055)/1.055,2.4)});return .2126*r+.7152*g+.0722*b};
function themeVars(c){c=/^#[0-9a-f]{6}$/i.test(c||'')&&lum(c)<=.35?c:'#9d4a62';return{c,c2:mixc(c,'#ffffff',.28),soft:mixc(c,'#ffffff',.9),soft2:mixc(c,'#ffffff',.84),dk:mixc(c,'#000000',.35)}}
function applyTheme(c){const t=themeVars(c),r=document.documentElement.style;r.setProperty('--c',t.c);r.setProperty('--c2',t.c2);r.setProperty('--soft',t.soft);r.setProperty('--soft2',t.soft2);r.setProperty('--dk',t.dk);try{localStorage.setItem('theme_c',t.c)}catch{}document.querySelector('meta[name=theme-color]')?.setAttribute('content',t.c)}
const BRAND=()=>getComputedStyle(document.documentElement).getPropertyValue('--c').trim()||'#9d4a62';
function thm(css){const t=themeVars(BRAND());return css.replace(/#9d4a62/gi,t.c).replace(/#c97b92/gi,t.c2).replace(/#f6eef1/gi,mixc(t.c,'#ffffff',.91)).replace(/#fbf6f8/gi,mixc(t.c,'#ffffff',.95)).replace(/#f0dce3/gi,t.soft2).replace(/#f4e6eb/gi,t.soft)}
function pickTheme(c){const i=$('#vc');if(i)i.value=c;applyTheme(c)}
applyTheme(localStorage.getItem('theme_c'));
const CSTD={lead:"LEAD BARU (INQUIRY)\nCalon client yang baru menghubungi atau bertanya, tetapi belum ada meeting maupun penawaran (tahap pipeline = inquiry).\nTindak lanjut: sapa, kirim paket/katalog, lalu tawarkan meeting.",meeting:"TAHAP MEETING\nCalon client yang sudah dijadwalkan atau sudah bertemu/konsultasi, namun belum menerima penawaran harga.\nTindak lanjut: kirim ringkasan hasil meeting dan penawaran.",penawaran:"TAHAP PENAWARAN\nPenawaran harga sudah dikirim dan sedang menunggu keputusan client.\nTindak lanjut: pastikan sudah dibaca, tawarkan negosiasi atau bonus DP.",deal:"DEAL\nClient sudah setuju dan melanjutkan (tahap pipeline = deal), biasanya sudah punya booking. Dipakai untuk menghitung angka konversi.",batal:"BATAL\nCalon client memutuskan tidak jadi atau tidak merespons lagi, lalu ditutup (tahap pipeline = batal). Tetap dihitung sebagai bagian dari total lead untuk konversi.",booking:"PUNYA BOOKING AKTIF\nClient memiliki minimal satu booking yang tidak berstatus cancelled.",bookbatal:"BOOKING DIBATALKAN\nClient memiliki booking berstatus cancelled.\nTindak lanjut: cek alasan pembatalan dan peluang menjadwalkan ulang.",fuaktif:"FOLLOW-UP TERJADWAL\nClient memiliki tugas follow-up yang belum dikerjakan (status terjadwal), artinya sudah ada rencana pendekatan.",futelat:"FOLLOW-UP TERLAMBAT\nAda tugas follow-up terjadwal yang tanggalnya sudah lewat tetapi belum dikerjakan.\nTindak lanjut: prioritas untuk dihubungi hari ini.",funone:"LEAD BELUM ADA FOLLOW-UP\nCalon client masih di tahap inquiry, meeting, atau penawaran, tetapi tidak punya satu pun tugas follow-up terjadwal sehingga berisiko terlupakan.\nTindak lanjut: buat follow-up dengan tombol + FU.",noinv:"BOOKING BELUM ADA INVOICE\nClient sudah punya booking aktif tetapi belum ada satu pun invoice (tagihan) untuk booking tersebut.\nTindak lanjut: buat invoice DP atau jadwal cicilan.",unpaid:"INVOICE BELUM LUNAS\nClient memiliki minimal satu invoice yang belum terbayar penuh (masih ada sisa tagihan).\nTindak lanjut: kirim pengingat pembayaran.",nobook:"BELUM BOOKING\nClient belum memiliki booking aktif dan belum berstatus batal: masih calon client."};
